import json,sys,os
base='/private/var/tmp/own023-r3/B-claude/work/gala/app/components'
lim=int(sys.argv[1])
for c in sys.argv[2:]:
  d=os.path.join(base,c)
  m=json.load(open(d+'/component.json'))
  print('=====',c,'|',m.get('description',''))
  for k in m:
    if k not in('$schema','id','name','path','created','modified','modifiedBy','description'): print(' meta',k,json.dumps(m[k],ensure_ascii=False)[:800])
